/**
 * PagerDuty v3 webhook continuation fixtures shared by the two continuation
 * vocabulary copies: `internal/continuation-identity.ts` (BDK) and the
 * control plane's `agentSdkConversationIdentity.ts` (server-shared). Both
 * suites import this module, so a payload shape or key format that only one
 * copy understands fails CI on the other side.
 *
 * Pure data and payload builders: no imports, so the server-shared suite
 * can load it by relative path without pulling `@grok/agent-sdk` into the
 * control plane.
 */
const SERVICE = {
    id: "PSVC001",
    type: "service_reference",
    summary: "checkout-api",
    html_url: "https://acme.pagerduty.com/service-directory/PSVC001",
};
const ESCALATION_POLICY = {
    id: "PPOL001",
    type: "escalation_policy_reference",
    summary: "checkout first responder",
};
/** The deployment's own PagerDuty user in these fixtures. */
export const PAGERDUTY_FIXTURE_SELF_USER_ID = "PBOT001";
export const PAGERDUTY_FIXTURE_HUMAN_USER_ID = "PHUM001";
export function pagerDutyUserReference(id) {
    return {
        id,
        type: "user_reference",
        summary: id === PAGERDUTY_FIXTURE_SELF_USER_ID ? "Responder bot" : "Dana Oncall",
        html_url: `https://acme.pagerduty.com/users/${id}`,
    };
}
export function pagerDutyIncidentData(input) {
    return {
        id: input.id,
        type: "incident",
        self: `https://api.pagerduty.com/incidents/${input.id}`,
        html_url: `https://acme.pagerduty.com/incidents/${input.id}`,
        number: input.number ?? 4012,
        status: input.status ?? "triggered",
        incident_key: input.incidentKey,
        created_at: "2026-10-12T09:45:01Z",
        title: "checkout-api error rate above 5%",
        service: SERVICE,
        escalation_policy: ESCALATION_POLICY,
        assignees: [pagerDutyUserReference(PAGERDUTY_FIXTURE_SELF_USER_ID)],
        teams: [{ id: "PTEAM01", type: "team_reference", summary: "Checkout" }],
        priority: { id: "PPRI001", type: "priority_reference", summary: "P2" },
        urgency: "high",
        conference_bridge: null,
        resolve_reason: null,
    };
}
export function pagerDutyIncidentReference(input) {
    const reference = {
        id: input.id,
        type: "incident_reference",
        self: `https://api.pagerduty.com/incidents/${input.id}`,
        html_url: `https://acme.pagerduty.com/incidents/${input.id}`,
        summary: "checkout-api error rate above 5%",
    };
    if (input.incidentKey !== undefined) {
        reference.incident_key = input.incidentKey;
    }
    return reference;
}
/** One signed v3 delivery body: `{ event: { … } }`. */
export function pagerDutyWebhookBody(input) {
    return {
        event: {
            id: input.eventId ?? `01EVT${input.eventType.replace(/[^a-z]/g, "").toUpperCase()}`,
            event_type: input.eventType,
            resource_type: input.resourceType ?? "incident",
            occurred_at: "2026-10-12T09:45:02.311Z",
            agent: input.agentId === null
                ? null
                : pagerDutyUserReference(input.agentId ?? PAGERDUTY_FIXTURE_HUMAN_USER_ID),
            client: { name: "PagerDuty" },
            data: input.data,
        },
    };
}
const DEDUP_KEY = "datadog-monitor-81234567";
export const PAGERDUTY_CONTINUATION_FIXTURES = [
    {
        name: "triggered incident keys on its id",
        eventType: "incident.triggered",
        payload: pagerDutyWebhookBody({
            eventType: "incident.triggered",
            agentId: null,
            data: pagerDutyIncidentData({ id: "PINC001", incidentKey: DEDUP_KEY }),
        }),
        expectedKey: "cont:pagerduty:incident:PINC001",
    },
    {
        name: "a re-trigger after resolve is a new incident and a new lane",
        eventType: "incident.triggered",
        payload: pagerDutyWebhookBody({
            eventType: "incident.triggered",
            agentId: null,
            data: pagerDutyIncidentData({ id: "PINC002", incidentKey: DEDUP_KEY, number: 4013 }),
        }),
        expectedKey: "cont:pagerduty:incident:PINC002",
    },
    {
        name: "a lifecycle event by a person stays on the incident",
        eventType: "incident.acknowledged",
        payload: pagerDutyWebhookBody({
            eventType: "incident.acknowledged",
            data: pagerDutyIncidentData({
                id: "PINC001",
                incidentKey: DEDUP_KEY,
                status: "acknowledged",
            }),
        }),
        expectedKey: "cont:pagerduty:incident:PINC001",
    },
    {
        name: "an incident with no dedup key keys on its id",
        eventType: "incident.triggered",
        payload: pagerDutyWebhookBody({
            eventType: "incident.triggered",
            data: pagerDutyIncidentData({ id: "PMAN001", incidentKey: null }),
        }),
        expectedKey: "cont:pagerduty:incident:PMAN001",
    },
    {
        name: "a note joins the incident it names, not the note id",
        eventType: "incident.annotated",
        payload: pagerDutyWebhookBody({
            eventType: "incident.annotated",
            data: {
                id: "PNOTE01",
                type: "incident_note",
                content: "Rolled back the 09:30 deploy.",
                trimmed: false,
                incident: pagerDutyIncidentReference({ id: "PINC001" }),
            },
        }),
        expectedKey: "cont:pagerduty:incident:PINC001",
    },
    {
        name: "a responder event joins the incident it names",
        eventType: "incident.responder.added",
        payload: pagerDutyWebhookBody({
            eventType: "incident.responder.added",
            data: {
                type: "incident_responder",
                user: pagerDutyUserReference("PDBA001"),
                escalation_policy: ESCALATION_POLICY,
                message: "Please join the database investigation.",
                state: "pending",
                incident: pagerDutyIncidentReference({ id: "PINC001" }),
            },
        }),
        expectedKey: "cont:pagerduty:incident:PINC001",
    },
    {
        name: "a service event is outside the incident membership",
        eventType: "service.updated",
        payload: pagerDutyWebhookBody({
            eventType: "service.updated",
            resourceType: "service",
            data: { ...SERVICE, type: "service" },
        }),
        expectedKey: undefined,
    },
    {
        name: "an incident event without incident data stamps evt:",
        eventType: "incident.triggered",
        payload: pagerDutyWebhookBody({ eventType: "incident.triggered", data: null }),
        expectedKey: undefined,
    },
];
